import{_ as s,C as i,o as t,c as d,a5 as a,b as n,w as r,a as l,E as c,a7 as h}from"./chunks/framework.QWVCgkrI.js";const B=JSON.parse('{"title":"Gitのrevert — 履歴を消さずに変更を打ち消す仕組み","description":"","frontmatter":{"title":"Gitのrevert — 履歴を消さずに変更を打ち消す仕組み","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"元のコミットが親の経路に残る理由を読み、後続変更の保持、テキスト競合、ゲームの仕様上の不整合を比べる。","aliases":["Git revert","リバート","取り消しコミット","逆変更","共有履歴"],"verification":"Git公式資料と照合し、Windowsの独立リポジトリで通常コミットのrevert、競合、仕様上の不整合を確認（2026-11-17）"}},"headers":[],"relativePath":"tools/git-revert.md","filePath":"tools/git-revert.md"}'),p={name:"tools/git-revert.md"};function m(g,e,E,A,u,b){const o=i("Mermaid");return t(),d("div",null,[e[1]||(e[1]=a('<h1 id="gitのrevert-—-履歴を消さずに変更を打ち消す仕組み" tabindex="-1">Gitのrevert — 履歴を消さずに変更を打ち消す仕組み <a class="header-anchor" href="#gitのrevert-—-履歴を消さずに変更を打ち消す仕組み" aria-label="Permalink to &quot;Gitのrevert — 履歴を消さずに変更を打ち消す仕組み&quot;">​</a></h1><p>敵のHPを上げたあと、別のコミットでゲーム内のステージ番号を変えたとします。HPだけを前の値に戻したいなら、Gitの <code>revert</code> でHPを下げる変更を新しいコミットとして積めます。後から履歴を読むと、HPを上げた経緯と取り消した経緯の両方が分かります。<a href="https://git-scm.com/docs/git-revert#_description" target="_blank" rel="noreferrer">Git公式のrevertマニュアル</a></p><h2 id="この記事で分かること" tabindex="-1">この記事で分かること <a class="header-anchor" href="#この記事で分かること" aria-label="Permalink to &quot;この記事で分かること&quot;">​</a></h2><p>過去の変更を打ち消すコミットがどこに積まれ、後続の変更がどう残るか説明できます。Git上の競合とゲームの仕様上の不整合を別々に判断できます。</p><p><strong>どんなときに使うか</strong>　共有済みの履歴に、特定の変更を打ち消した経緯を残したいときです。</p><h2 id="親との差を逆向きにし、現在の先端へ適用する" tabindex="-1">親との差を逆向きにし、現在の先端へ適用する <a class="header-anchor" href="#親との差を逆向きにし、現在の先端へ適用する" aria-label="Permalink to &quot;親との差を逆向きにし、現在の先端へ適用する&quot;">​</a></h2><p>親を一つ持つ通常のコミットBを考えます。<strong>親</strong>は、直前の状態を記録したコミットです。親AからBへの差が、Bで加えた変更です。</p><p>GitはBをrevertするとき、BからAへの逆向きの変更を、実行時の先端Cに適用しようとします。適用が成功して逆変更が生じると、通常の実行ではCを親とするDが作られます。後続のCで加えた変更も残り得ます。<a href="https://git-scm.com/docs/git-revert#_description" target="_blank" rel="noreferrer">Git公式のrevertマニュアル</a> · <a href="/study/tools/git-objects.html">Gitの保存モデル</a></p><p>図の矢印は、コミットからその親へ向きます。最初は <code>main</code> がCを指していて、revert後はDを指します。Dから親をたどるとC、B、Aの順に到達します。</p>',9)),(t(),n(h,null,{default:r(()=>[c(o,{id:"mermaid-27",class:"mermaid",graph:"---%0Aconfig%3A%0A%20%20flowchart%3A%0A%20%20%20%20nodeSpacing%3A%2020%0A%20%20%20%20rankSpacing%3A%2034%0A%20%20%20%20padding%3A%208%0A---%0Aflowchart%20TD%0A%20%20%20%20accTitle%3A%20revert%E5%BE%8C%E3%82%82%E5%85%83%E3%81%AE%E3%82%B3%E3%83%9F%E3%83%83%E3%83%88%E3%81%8C%E7%A5%96%E5%85%88%E3%81%AB%E6%AE%8B%E3%82%8B%0A%20%20%20%20accDescr%3A%20revert%E5%BE%8C%E3%81%AEmain%E3%81%AFD%E3%82%92%E6%8C%87%E3%81%99%E3%80%82D%E3%81%AE%E8%A6%AA%E3%81%AFC%E3%80%81C%E3%81%AE%E8%A6%AA%E3%81%AF%E5%85%83%E3%81%AEHP%E5%A4%89%E6%9B%B4B%E3%80%81B%E3%81%AE%E8%A6%AA%E3%81%AFA%E3%80%82D%E3%81%A7%E3%81%AFHP%E3%81%A0%E3%81%91%E3%82%9210%E3%81%AB%E6%88%BB%E3%81%97%E3%80%81%E3%82%B9%E3%83%86%E3%83%BC%E3%82%B82%E3%82%92%E4%BF%9D%E6%8C%81%E3%81%99%E3%82%8B%E3%80%82%0A%20%20%20%20branch%5B%22main%20%E3%81%AE%E5%85%88%E7%AB%AF%22%5D%20--%3E%20d%5B%22D%20HP%E3%82%9210%E3%81%AB%E6%88%BB%E3%81%99%22%5D%0A%20%20%20%20d%20--%3E%7C%E8%A6%AA%7C%20c%5B%22C%20%E3%82%B9%E3%83%86%E3%83%BC%E3%82%B8%E3%82%922%E3%81%AB%E3%81%99%E3%82%8B%22%5D%0A%20%20%20%20c%20--%3E%7C%E8%A6%AA%7C%20b%5B%22B%20HP%E3%82%9220%E3%81%AB%E4%B8%8A%E3%81%92%E3%82%8B%22%5D%0A%20%20%20%20b%20--%3E%7C%E8%A6%AA%7C%20a%5B%22A%20HP10%E3%83%BB%E3%82%B9%E3%83%86%E3%83%BC%E3%82%B81%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<h2 id="hpを戻しても、ステージ番号は残る" tabindex="-1">HPを戻しても、ステージ番号は残る <a class="header-anchor" href="#hpを戻しても、ステージ番号は残る" aria-label="Permalink to &quot;HPを戻しても、ステージ番号は残る&quot;">​</a></h2><p>Bが <code>enemy.txt</code> だけを変え、Cが <code>stage.txt</code> だけを変えた場合の実測です。Dの <code>enemy.txt</code> はAと同じ <code>hp=10</code> ですが、<code>stage.txt</code> はCで設定した <code>stage=2</code> です。AとDを比べると、ステージ番号に差が残ります。</p><table tabindex="0"><thead><tr><th>コミット</th><th><code>enemy.txt</code></th><th><code>stage.txt</code></th></tr></thead><tbody><tr><td>A 当初の状態</td><td><code>hp=10</code></td><td><code>stage=1</code></td></tr><tr><td>B HPを上げる</td><td><code>hp=20</code></td><td><code>stage=1</code></td></tr><tr><td>C ステージを変える</td><td><code>hp=20</code></td><td><code>stage=2</code></td></tr><tr><td>D Bをrevertする</td><td><code>hp=10</code></td><td><code>stage=2</code></td></tr></tbody></table><p>revert後の履歴とファイルを読んだ出力です。先頭にDが加わり、Bはその下に残っています。<code>git merge-base --is-ancestor 72445d2 HEAD</code> の終了コードは <code>0</code> で、Bが現在の先端の祖先であることも確かめられました。<a href="https://git-scm.com/docs/git-merge-base#_operation_modes" target="_blank" rel="noreferrer">Git公式のmerge-baseマニュアル</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git log -4 --format=&#39;%h %s&#39;</span></span>
<span class="line"><span>f49a284 Revert &quot;B: Raise enemy HP&quot;</span></span>
<span class="line"><span>0eb6c8c C: Advance stage</span></span>
<span class="line"><span>72445d2 B: Raise enemy HP</span></span>
<span class="line"><span>63fe8c4 A: Initial enemy and stage</span></span>
<span class="line"><span>$ git show HEAD:enemy.txt</span></span>
<span class="line"><span>hp=10</span></span>
<span class="line"><span>$ git show HEAD:stage.txt</span></span>
<span class="line"><span>stage=2</span></span>
<span class="line"><span>$ git diff --name-only 63fe8c4 HEAD</span></span>
<span class="line"><span>stage.txt</span></span></code></pre></div><h2 id="競合と、ゲームの仕様上の不整合" tabindex="-1">競合と、ゲームの仕様上の不整合 <a class="header-anchor" href="#競合と、ゲームの仕様上の不整合" aria-label="Permalink to &quot;競合と、ゲームの仕様上の不整合&quot;">​</a></h2><h3 id="後続コミットが同じ行を変えた場合" tabindex="-1">後続コミットが同じ行を変えた場合 <a class="header-anchor" href="#後続コミットが同じ行を変えた場合" aria-label="Permalink to &quot;後続コミットが同じ行を変えた場合&quot;">​</a></h3><p>Cの代わりに、Bの後で同じ行を <code>hp=30</code> にしたとします。Bの逆変更は、HPを <code>20</code> から <code>10</code> に変えるものです。現在の <code>30</code> と逆変更で求める <code>10</code> のどちらを残すかは、変更箇所の意図によって決まります。独立した例では、Gitが <code>enemy.txt</code> の競合を報告して停止し、新しいコミットは作られませんでした。<a href="https://git-scm.com/docs/git-revert" target="_blank" rel="noreferrer">Git公式のrevertマニュアル</a> · <a href="https://git-scm.com/docs/git-merge#_how_conflicts_are_presented" target="_blank" rel="noreferrer">Git公式の競合表示</a></p><h3 id="別のファイルが元の変更を前提にしていた場合" tabindex="-1">別のファイルが元の変更を前提にしていた場合 <a class="header-anchor" href="#別のファイルが元の変更を前提にしていた場合" aria-label="Permalink to &quot;別のファイルが元の変更を前提にしていた場合&quot;">​</a></h3><p>Bで敵のHPを <code>20</code> に上げたあと、別の設定ファイル <code>bonus.txt</code> に「HPが20以上の敵だけがボーナス対象」という条件（<code>min_hp=20</code>）を追加したとします。Bをrevertすると、Gitは <code>enemy.txt</code> のHPを <code>10</code> に戻し、条件の設定は残します。テキストの競合がなくても、この敵を対象にするという設計上の意図は満たせなくなります。別の検証例では、二つの設定値を読み、<code>hp &gt;= min_hp</code> がrevert前に <code>true</code>、revert後に <code>false</code> になることを確かめました。</p><h2 id="補足" tabindex="-1">補足 <a class="header-anchor" href="#補足" aria-label="Permalink to &quot;補足&quot;">​</a></h2><h3 id="共有済みの先端を置き換える場合との違い" tabindex="-1">共有済みの先端を置き換える場合との違い <a class="header-anchor" href="#共有済みの先端を置き換える場合との違い" aria-label="Permalink to &quot;共有済みの先端を置き換える場合との違い&quot;">​</a></h3><p>履歴からBを抜くためにCをAの上に作り直すと、Cの親が変わり、別のコミットになります。共有済みの履歴で先端を置き換えると、元のCを取得した他の人との履歴が分かれます。revertではDがCの子なので、共有先がCにいるなら、履歴上は先端を前に進める更新です。<a href="/study/tools/git-rebase.html">Gitのrebase</a> · <a href="/study/tools/git-remote-tracking.html">Gitのリモート追跡ブランチ</a></p><h3 id="マージコミットでは基準の親を選ぶ" tabindex="-1">マージコミットでは基準の親を選ぶ <a class="header-anchor" href="#マージコミットでは基準の親を選ぶ" aria-label="Permalink to &quot;マージコミットでは基準の親を選ぶ&quot;">​</a></h3><p>マージコミットMには複数の親があります。<code>git revert -m 1 M</code> の <code>1</code> は、Mがその第1親に対して導入した変更を打ち消す、という指定です。第1親も第2親も元の親関係に残ります。</p><p>あとで同じ作業ブランチを再びmergeしても、すでに祖先にあるコミットの変更が自動的にもう一度入るとは限りません。どの変更が入るかは、後続のコミットと<strong>マージベース</strong>（統合の基準にする共通祖先）によって変わります。このケースは公式資料での確認にとどめました。<a href="https://git-scm.com/docs/git-revert#_options" target="_blank" rel="noreferrer">Git公式の <code>--mainline</code></a> · <a href="https://github.com/git/git/blob/v2.39.2/Documentation/howto/revert-a-faulty-merge.txt" target="_blank" rel="noreferrer">Git公式のマージ取り消し解説</a> · <a href="/study/tools/git-three-way-merge.html">Gitのマージ</a></p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ul><li>通常のコミットのrevertでは、親との差を逆向きにして、現在の先端へ適用します。</li><li>取り消しをコミットすると、元のコミットも新しい先端の祖先として残ります。</li><li>例ではHPが10に戻り、後続コミットのステージ番号2は残りました。</li><li>同じ行の後続編集とは競合し得ます。競合せず適用できても、別の設定の条件が崩れることがあります。</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>Dを作ったあと、元のBはどこにある？</summary><p>Dから親をたどるとCの次がBです。Bの変更を打ち消した操作は、Cの先にDとして記録されています。</p></details><details class="details custom-block"><summary>Bを取り消すとステージ番号も1に戻る？</summary><p>この例では <code>stage=2</code> のままです。Bが変えたのは <code>enemy.txt</code> で、ステージ番号の変更はCにあります。</p></details><details class="details custom-block"><summary>テキストの競合がなければ、ゲームの仕様も保たれる？</summary><p>別の設定が打ち消された変更を前提にしている場合は、Gitがコミットを作れてもその前提が崩れます。HPが10に戻ると、HP20以上という条件を満たさなくなります。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月17日に、WindowsのGit 2.39.2.windows.1と独立したSHA-1リポジトリ3つを使いました。クリーンな作業ツリーで、親が一つのコミットを <code>git revert --no-edit</code> で取り消しました。別ファイルの後続変更を保持する例、同じ行で競合する例、競合なく適用できても仕様上の条件が崩れる例を確認しました。ボーナスの判定は設定ファイルを読む簡単な検査で、ゲームエンジン上の挙動、マージコミットのrevertとその後のmerge、競合解消後の結果、複数コミットを一度に取り消す場合は未検証です。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/tools/git-basics.html">Gitの基本</a> — 差分とコミットの関係を読む。</li><li><a href="/study/tools/git-objects.html">Gitの保存モデル</a> — スナップショットと親IDがコミットに入る仕組みを確認する。</li><li>コミット前に、指定した版へファイルの内容を戻す仕組みを読む。<a href="/study/tools/git-restore.html">Git restoreの仕組み — 履歴を動かさず、復元元と復元先を選ぶ</a></li><li>変更を打ち消すコミットを積む場合と、ブランチの先端を動かす場合を比べる。<a href="/study/tools/git-reset.html">Gitのreset — HEAD・index・作業ツリーはどう変わるのか</a></li><li><a href="/study/tools/git-three-way-merge.html">Gitのマージ</a> — テキストの競合と意味上の不整合を比べる。</li><li><a href="/study/tools/git-rebase.html">Gitのrebase</a> — 親を変えてコミットを作り直したときの履歴を読む。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/git-revert" target="_blank" rel="noreferrer">Git公式 — git-revert</a></li><li><a href="https://git-scm.com/docs/git-merge-base#_operation_modes" target="_blank" rel="noreferrer">Git公式 — git-merge-base</a></li><li><a href="https://git-scm.com/docs/git-merge#_how_conflicts_are_presented" target="_blank" rel="noreferrer">Git公式 — git-merge</a></li><li><a href="https://github.com/git/git/blob/v2.39.2/Documentation/howto/revert-a-faulty-merge.txt" target="_blank" rel="noreferrer">Git公式 — Revert a faulty merge（Git 2.39.2）</a></li></ul>`,28))])}const _=s(p,[["render",m]]);export{B as __pageData,_ as default};
